__global__ void convert_batch_panel_kernel(
    __half* __restrict__ converted,
    const float* __restrict__ source,
    long long group_count,
    int rows,
    int col_groups,
    long long converted_stride_0,
    long long converted_stride_1,
    long long source_stride_0,
    long long source_stride_1
) {
