             static_cast<long long>(blockIdx.x) * blockDim.x + threadIdx.x;
         index < group_count;
         index += step) {
        const int col_group = static_cast<int>(index % col_groups);
        const long long row_index = index / col_groups;
        const int row = static_cast<int>(row_index % rows);
        const long long batch = row_index / rows;
        const int col = col_group * 4;
