void convert_batch_panel_cuda(
    torch::Tensor panel, torch::Tensor converted
) {
    TORCH_CHECK(panel.is_cuda() && converted.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(
        panel.scalar_type() == torch::kFloat32
        && converted.scalar_type() == torch::kFloat16,
        "expected FP32 panel and FP16 converted output"
    );
    TORCH_CHECK(
        panel.sizes() == converted.sizes() && panel.dim() == 3,
        "panel conversion shapes must match"
    );
    TORCH_CHECK(
        panel.size(2) % 4 == 0 && panel.stride(2) == 1
        && converted.stride(2) == 1,
        "panel columns must be float4 aligned and contiguous"
    );
    const long long group_count = panel.numel() / 4;
    const int threads = 256;
    const int blocks = static_cast<int>((group_count + threads - 1) / threads);
    const int persistent_blocks = blocks < 4096 ? blocks : 4096;
    convert_batch_panel_kernel<<<
        persistent_blocks, threads, 0,
        c10::cuda::AC_CAT(getCurrentCUDA, AC_CAT(Str, eam))()
    >>>(
        reinterpret_cast<__half*>(converted.data_ptr<at::Half>()),
        panel.data_ptr<float>(),
        group_count,
        static_cast<int>(panel.size(1)),
        static_cast<int>(panel.size(2) / 4),
        converted.stride(0),
        converted.stride(1),
        panel.stride(0),
        panel.stride(1)
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
}

__global__ void lower_copy_kernel(
        const float* source, float* output, int n) {
    const int row = static_cast<int>(blockIdx.x);
    const int full_vectors = (row + 1) >> 2;
    const int64_t base = static_cast<int64_t>(row) * n;
    const float4* source_vectors = reinterpret_cast<const float4*>(
        source + base);
    float4* output_vectors = reinterpret_cast<float4*>(output + base);
    for (int vector = threadIdx.x; vector < full_vectors;
         vector += blockDim.x) {
        output_vectors[vector] = source_vectors[vector];
    }
    const int tail = full_vectors << 2;
    for (int col = tail + threadIdx.x; col <= row; col += blockDim.x) {
        output[base + col] = source[base + col];
    }
}

void lower_copy_(torch::Tensor input, torch::Tensor output) {
    TORCH_CHECK(input.is_cuda() && output.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(input.scalar_type() == at::kFloat &&
                output.scalar_type() == at::kFloat,
                "FP32 tensors required");
    TORCH_CHECK(input.dim() == 3 && input.size(0) == 1 &&
                input.size(1) == input.size(2) &&
                input.is_contiguous() && output.is_contiguous() &&
                input.sizes() == output.sizes(),
                "matching contiguous batch-one matrices required");
    const int n = static_cast<int>(input.size(1));
    TORCH_CHECK((n & 3) == 0, "matrix width must be float4 aligned");
    lower_copy_kernel<<<
        n, 256, 0,
        c10::cuda::AC_CAT(getCurrentCUDA, AC_CAT(Str, eam))()>>>(
            input.data_ptr<float>(), output.data_ptr<float>(), n);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
}

__global__ void copy_factor_lower_kernel(
        const float* factor, float* output, int leading_output) {
    constexpr int tile_size = 32;
    __shared__ float tile[tile_size][tile_size + 1];
    const int tile_col = static_cast<int>(blockIdx.x);
    const int tile_row = static_cast<int>(blockIdx.y);
    if (tile_row < tile_col) {
        const int row_base = tile_row * tile_size;
        const int col_base = tile_col * tile_size;
        for (int y = threadIdx.y; y < tile_size; y += blockDim.y) {
            output[
                static_cast<int64_t>(row_base + y) * leading_output
                + col_base + threadIdx.x
            ] = 0.0f;
        }
        return;
    }
    const int tx = threadIdx.x;
    const int row_base = tile_row * tile_size;
    const int col_base = tile_col * tile_size;
    for (int y = threadIdx.y; y < tile_size; y += blockDim.y) {
        tile[y][tx] = factor[
            row_base + tx + static_cast<int64_t>(col_base + y) * 4096
        ];
    }
    __syncthreads();
    for (int y = threadIdx.y; y < tile_size; y += blockDim.y) {
        const int row = row_base + y;
        const int col = col_base + tx;
        output[static_cast<int64_t>(row) * leading_output + col] =
            row >= col ? tile[tx][y] : 0.0f;
    }
}

